insert into public.equipment (id, name, category, sort_order, common_at_home) values
  ('rotary_torso_machine', 'Rotary torso machine', 'machines', 88, false),
  ('back_extension_machine', 'Back extension machine (seated)', 'machines', 89, false),
  ('sliders', 'Sliders / gliding discs', 'accessories', 90, true),
  ('hand_gripper', 'Hand gripper', 'accessories', 91, true)
insert into public.exercises (id, name, aliases, category, movement_pattern, mechanic, force, level, instructions, images, is_common, is_active, source) values
  ('Assisted_Chin-Up', 'Assisted Chin-Up', array['Assisted Chinup', 'Machine Chin-Up']::text[], 'strength', 'vertical_pull', 'compound', 'pull', 'beginner', array['Set the assistance weight, kneel or stand on the pad, and grip the bar with an underhand grip.', 'Pull your chest toward the bar until your chin clears it.', 'Lower slowly to straight arms. Use less assistance over time.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Band_Straight-Arm_Pulldown', 'Band Straight-Arm Pulldown', array['Resistance Band Straight-Arm Pulldown', 'Band Lat Pullover']::text[], 'strength', 'vertical_pull', 'isolation', 'pull', 'beginner', array['Anchor a band overhead, face it, and hold the ends with straight arms in front of you at shoulder height.', 'Keeping your arms straight, sweep your hands down to your thighs.', 'Return slowly with control, feeling your lats stretch.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Jumping_Pull-Up', 'Jumping Pull-Up', array['Jump Pull-Up', 'Jumping Chin-Up']::text[], 'strength', 'vertical_pull', 'compound', 'pull', 'beginner', array['Stand under a pull-up bar with a grip a little wider than your shoulders.', 'Jump up and pull with your arms until your chin is over the bar.', 'Lower yourself slowly for 3 to 5 seconds. Great for building up to full pull-ups.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Suspension_Bicep_Curl', 'Suspension Bicep Curl', array['TRX Bicep Curl', 'Ring Bicep Curl']::text[], 'strength', 'isolation', 'isolation', 'pull', 'beginner', array['Hold the handles with palms up and lean back with straight arms, feet planted.', 'Curl your hands toward your forehead, keeping your elbows high and still.', 'Lower slowly. Step your feet closer to make it harder.']::text[], '{}'::text[], true, true, 'catalog'),
  ('HIIT_Class', 'HIIT Class', array['HIIT Workout', 'High Intensity Interval Training', 'Circuit Class']::text[], 'cardio', 'cardio', null, null, 'beginner', array['Warm up for 5 minutes with easy movement.', 'Work through the class intervals, giving a hard effort in each work period and resting in the breaks.', 'Log the total time and cool down for a few minutes.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Pilates_Session', 'Pilates Session', array['Pilates', 'Pilates Class', 'Mat Pilates']::text[], 'cardio', 'cardio', null, null, 'beginner', array['Set up on a mat in a quiet space.', 'Follow the class or routine, moving with control and keeping your core braced and breathing steady.', 'Log the total time at the end.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Rucking', 'Rucking', array['Ruck', 'Weighted Walk', 'Loaded Hike']::text[], 'cardio', 'cardio', null, null, 'beginner', array['Load a backpack or weight vest with a comfortable weight, usually 10 to 30 pounds to start.', 'Walk at a brisk pace, standing tall with the weight snug on your back.', 'Log your distance and time, and add weight slowly over the weeks.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Yoga_Session', 'Yoga Session', array['Yoga', 'Yoga Class', 'Vinyasa']::text[], 'cardio', 'cardio', null, null, 'beginner', array['Set up on a mat in a quiet space.', 'Flow through poses with your breath, holding each for a few breaths.', 'Log the total time at the end.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Decline_Cable_Fly', 'Decline Cable Fly', array['Cable Decline Fly', 'High-to-Low Cable Fly']::text[], 'strength', 'isolation', 'isolation', 'push', 'intermediate', array['Set the pulleys high, hold a handle in each hand, and step forward with a slight lean.', 'With a soft bend in your elbows, sweep your hands down and together in front of your hips.', 'Return slowly until you feel a stretch across your chest.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Hindu_Push-Up', 'Hindu Push-Up', array['Hindu Pushup', 'Dive Bomber Push-Up']::text[], 'strength', 'horizontal_push', 'compound', 'push', 'intermediate', array['Start in a pike position with your hips high and hands shoulder-width apart.', 'Dive your chest down and forward toward the floor, then sweep up into an upward dog with your hips low.', 'Reverse the motion back to the pike position.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Lying_Cable_Pullover', 'Lying Cable Pullover', array['Cable Pullover Lying', 'Supine Cable Pullover']::text[], 'strength', 'isolation', 'isolation', 'pull', 'intermediate', array['Lie on a bench with your head toward a low cable and hold the bar or rope overhead with straight arms.', 'Keeping your arms nearly straight, pull the handle up and over your chest.', 'Return slowly until your lats are fully stretched.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Paused_Bench_Press', 'Paused Bench Press', array['Pause Bench Press', 'Pause Bench']::text[], 'strength', 'horizontal_push', 'compound', 'push', 'intermediate', array['Set up on the bench as for a normal bench press, with feet planted and shoulder blades pinched.', 'Lower the bar to your chest and hold it still there for 1 to 2 seconds without bouncing.', 'Press it back up to straight arms.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Single-Arm_Cable_Chest_Press', 'Single-Arm Cable Chest Press', array['One-Arm Cable Press', 'Standing Single-Arm Cable Press']::text[], 'strength', 'horizontal_push', 'compound', 'push', 'beginner', array['Set a cable at chest height and stand facing away, holding the handle by your chest in a split stance.', 'Press the handle straight out until your arm is straight, without letting your torso twist.', 'Return slowly and repeat all reps, then switch sides.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Spiderman_Push-Up', 'Spiderman Push-Up', array['Spider-Man Push-Up', 'Spiderman Pushup']::text[], 'strength', 'horizontal_push', 'compound', 'push', 'intermediate', array['Start in a push-up position with your body in a straight line.', 'As you lower your chest, lift one knee out to the side toward your elbow.', 'Press up, return the leg, and alternate sides.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Suspension_Chest_Fly', 'Suspension Chest Fly', array['TRX Chest Fly', 'Ring Fly']::text[], 'strength', 'isolation', 'isolation', 'push', 'intermediate', array['Hold the handles in a plank-like lean forward, arms straight out to your sides at chest height.', 'Bring your hands together in front of you with a slight bend in your elbows.', 'Open back out slowly. Step your feet back to make it easier.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Burpee_Box_Jump-Over', 'Burpee Box Jump-Over', array['Burpee Box Jump Over']::text[], 'strength', 'other', 'compound', 'push', 'intermediate', array['Stand facing a box, do a burpee, then jump up onto the box with both feet.', 'Step or jump down on the other side.', 'Turn around and repeat.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Devil_Press', 'Devil Press', array['Dumbbell Devil Press', 'Devil''s Press']::text[], 'strength', 'other', 'compound', 'push', 'expert', array['Hold dumbbells and set them on the floor, then do a burpee with your hands on them.', 'Stand up and swing both dumbbells in one motion from the floor to overhead.', 'Lower them to the floor under control and go into the next rep.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Double-Unders', 'Double-Unders', array['Double Unders', 'DUs', 'Double Jump Rope']::text[], 'strength', 'other', null, null, 'intermediate', array['Hold the rope handles at your hips and jump slightly higher than for normal skipping.', 'Spin the rope with your wrists so it passes twice under your feet in one jump.', 'Land softly on the balls of your feet and keep a steady rhythm.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Medicine_Ball_Rotational_Throw', 'Medicine Ball Rotational Throw', array['Rotational Med Ball Throw', 'Medicine Ball Side Throw']::text[], 'strength', 'core', 'compound', 'push', 'beginner', array['Stand sideways to a wall holding a medicine ball at your hip, with your knees soft.', 'Rotate your hips and torso and throw the ball hard against the wall.', 'Catch it, reset, and repeat all reps, then switch sides.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Shadow_Boxing', 'Shadow Boxing', array['Shadowboxing', 'Boxing Drills']::text[], 'strength', 'other', null, null, 'beginner', array['Stand in a boxing stance with your hands up and knees slightly bent.', 'Throw punches in combinations such as jab, cross, and hook, moving your feet lightly.', 'Work in rounds of 2 to 3 minutes with short rests.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Bear_Plank_Hold', 'Bear Plank Hold', array['Bear Hold', 'Bear Position Hold']::text[], 'strength', 'core', 'compound', 'static', 'beginner', array['Start on your hands and knees, then lift your knees about an inch off the floor.', 'Keep your back flat and your hips level, with your knees under your hips.', 'Hold as long as you can while breathing steadily.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Body_Saw', 'Body Saw', array['Suspension Body Saw', 'TRX Body Saw']::text[], 'strength', 'core', 'compound', 'static', 'intermediate', array['Place your feet in the straps or rings and get in a forearm plank.', 'Rock your body backward and forward a few inches, keeping your body in a straight line.', 'Control the movement from your core, not your lower back.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Bosu_Crunch', 'Bosu Crunch', array['BOSU Crunch', 'Bosu Ball Crunch']::text[], 'strength', 'core', 'isolation', 'pull', 'beginner', array['Sit on the dome of a BOSU ball and lean back so your lower back is supported, feet on the floor.', 'Curl your shoulders toward your hips, squeezing your abs.', 'Lower back slowly without letting your back collapse.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Decline_Sit-Up', 'Decline Sit-Up', array['Decline Situp', 'Decline Bench Sit-Up']::text[], 'strength', 'core', 'compound', 'pull', 'intermediate', array['Lie on a decline bench with your feet secured and your arms crossed over your chest.', 'Curl up until your torso is upright.', 'Lower slowly until your back is just above the bench.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Front_Rack_Carry', 'Front Rack Carry', array['Front Rack Walk', 'Kettlebell Front Rack Carry']::text[], 'strength', 'carry', 'compound', 'pull', 'beginner', array['Hold weights at your shoulders in the front rack position, elbows close to your ribs.', 'Walk a set distance with your ribs down and your torso tall.', 'Set the weights down with control.']::text[], '{}'::text[], true, true, 'catalog'),
  ('High_Plank', 'High Plank', array['Straight-Arm Plank', 'Full Plank']::text[], 'strength', 'core', 'compound', 'static', 'beginner', array['Place your hands under your shoulders with arms straight and feet hip-width apart.', 'Keep your body in a straight line from head to heels, squeezing your glutes and abs.', 'Hold as long as you can without letting your hips sag.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Hollow_Rock', 'Hollow Rock', array['Hollow Body Rock']::text[], 'strength', 'core', 'isolation', 'pull', 'intermediate', array['Get into a hollow hold: on your back, lower back pressed down, shoulders and legs lifted.', 'Rock back and forth like a rocking chair while keeping that shape.', 'Keep the movement small and smooth without losing your lower back contact.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Overhead_Carry', 'Overhead Carry', array['Overhead Walk', 'Waiter Walk', 'Kettlebell Overhead Carry']::text[], 'strength', 'carry', 'compound', 'pull', 'intermediate', array['Press a dumbbell or kettlebell overhead with a locked arm, ribs down.', 'Walk a set distance, keeping the weight stacked over your shoulder.', 'Lower it with control, then switch arms.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Plank_Jacks', 'Plank Jacks', array['Plank Jack']::text[], 'strength', 'core', 'compound', 'static', 'beginner', array['Start in a high plank with your feet together.', 'Jump your feet out wide, then back together, keeping your hips level.', 'Keep your core braced and your shoulders over your hands.']::text[], '{}'::text[], true, true, 'catalog'),
  ('RKC_Plank', 'RKC Plank', array['Hardstyle Plank', 'Max Tension Plank']::text[], 'strength', 'core', 'compound', 'static', 'intermediate', array['Get in a forearm plank with your elbows a little in front of your shoulders.', 'Squeeze everything hard: clench your fists, glutes, quads, and pull your elbows toward your toes.', 'Hold for 10 to 20 seconds. Quality beats duration here.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Rotary_Torso_Machine', 'Rotary Torso Machine', array['Torso Rotation Machine', 'Seated Torso Rotation']::text[], 'strength', 'core', 'isolation', 'pull', 'beginner', array['Sit in the machine, set the pads, and hold the handles or cross your arms.', 'Rotate your torso to one side against the resistance, keeping your hips still.', 'Return slowly and repeat, then work the other side.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Side_Plank_Hip_Dip', 'Side Plank Hip Dip', array['Side Plank Hip Drop', 'Side Plank Dips']::text[], 'strength', 'core', 'isolation', 'static', 'beginner', array['Get in a side plank on your forearm with your body in a straight line.', 'Lower your hips toward the floor, then raise them back up past the start.', 'Repeat all reps, then switch sides.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Slider_Mountain_Climber', 'Slider Mountain Climber', array['Sliding Mountain Climber', 'Gliding Mountain Climber']::text[], 'strength', 'core', 'compound', 'pull', 'intermediate', array['Get in a plank with your feet on sliders or towels on a smooth floor.', 'Slide one knee toward your chest, then switch legs in a running motion.', 'Keep your hips low and level, and move smoothly.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Standing_Oblique_Crunch', 'Standing Oblique Crunch', array['Standing Side Crunch', 'Standing Knee to Elbow']::text[], 'strength', 'core', 'isolation', 'pull', 'beginner', array['Stand tall with one hand behind your head.', 'Lift the knee on the same side up and out while crunching your elbow down toward it.', 'Return and repeat all reps, then switch sides.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Stir_the_Pot', 'Stir the Pot', array['Stability Ball Stir the Pot', 'Swiss Ball Stir the Pot']::text[], 'strength', 'core', 'compound', 'static', 'intermediate', array['Get in a forearm plank with your forearms on a stability ball.', 'Make small circles with your forearms, as if stirring a pot, keeping your body still.', 'Do the same number of circles in each direction.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Weighted_Dead_Bug', 'Weighted Dead Bug', array['Dumbbell Dead Bug', 'Dead Bug With Weight']::text[], 'strength', 'core', 'isolation', 'pull', 'intermediate', array['Lie on your back holding a dumbbell or kettlebell straight above your chest, knees bent at 90 degrees above your hips.', 'Lower the opposite arm and leg toward the floor while keeping your lower back pressed down.', 'Return and alternate sides.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Hand_Gripper', 'Hand Gripper', array['Grip Trainer', 'Captains of Crush', 'Grip Crusher']::text[], 'strength', 'isolation', 'isolation', 'pull', 'beginner', array['Hold the gripper in your palm with the handles apart.', 'Squeeze until the handles meet.', 'Release slowly. Complete all reps, then switch hands.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Band_Seated_Hip_Abduction', 'Band Seated Hip Abduction', array['Seated Band Abduction', 'Seated Banded Hip Abduction']::text[], 'strength', 'isolation', 'isolation', 'pull', 'beginner', array['Sit on a bench or chair with a band around your thighs just above your knees.', 'Push your knees apart against the band.', 'Hold briefly, then return slowly.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Frog_Pump', 'Frog Pump', array['Frog Glute Bridge', 'Frog Bridge']::text[], 'strength', 'isolation', 'isolation', 'push', 'beginner', array['Lie on your back with the soles of your feet together and knees falling out to the sides.', 'Drive your hips up by squeezing your glutes.', 'Lower under control and repeat for high reps.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Side-Lying_Hip_Adduction', 'Side-Lying Hip Adduction', array['Side-Lying Adduction', 'Inner Thigh Lift']::text[], 'strength', 'isolation', 'isolation', 'pull', 'beginner', array['Lie on your side with your top leg bent and foot on the floor in front of you.', 'Lift your bottom leg straight up toward the ceiling.', 'Lower slowly and repeat, then switch sides.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Bodyweight_Step-Up', 'Bodyweight Step-Up', array['Step-Up', 'Box Step-Up', 'Bench Step-Up']::text[], 'strength', 'lunge', 'compound', 'push', 'beginner', array['Stand facing a box or bench and place one foot fully on top.', 'Drive through that foot to stand up on the box, without pushing off the floor foot.', 'Step back down slowly. Complete all reps, then switch legs.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Cable_Standing_Leg_Curl', 'Cable Standing Leg Curl', array['Standing Cable Leg Curl', 'Cable Hamstring Curl']::text[], 'strength', 'isolation', 'isolation', 'pull', 'beginner', array['Attach an ankle strap to a low cable, strap it on, and hold a support for balance.', 'Curl your heel toward your glute without leaning forward.', 'Lower slowly. Complete all reps, then switch legs.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Cossack_Squat', 'Cossack Squat', array['Cossack Squats', 'Side-to-Side Squat']::text[], 'strength', 'squat', 'compound', 'push', 'intermediate', array['Stand in a wide stance with your toes turned slightly out.', 'Shift your weight to one side and squat down on that leg, keeping the other leg straight with the toes up.', 'Push back to the middle and go to the other side.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Dumbbell_Curtsy_Lunge', 'Dumbbell Curtsy Lunge', array['DB Curtsy Lunge', 'Weighted Curtsy Lunge']::text[], 'strength', 'lunge', 'compound', 'push', 'beginner', array['Hold dumbbells at your sides or one at your chest and stand tall.', 'Step one leg back and across behind you and lower until your front thigh is about parallel.', 'Drive back up and repeat, then switch sides.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Heel-Elevated_Goblet_Squat', 'Heel-Elevated Goblet Squat', array['Elevated Heel Goblet Squat', 'Heels Up Goblet Squat']::text[], 'strength', 'squat', 'compound', 'push', 'beginner', array['Place your heels on a small plate or wedge and hold a dumbbell or kettlebell at your chest.', 'Squat down between your knees, keeping your torso upright.', 'Drive back up. The raised heels let your knees travel further forward.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Pause_Squat', 'Pause Squat', array['Paused Squat', 'Paused Back Squat']::text[], 'strength', 'squat', 'compound', 'push', 'intermediate', array['Set up with the bar on your upper back and unrack it as for a normal squat.', 'Squat to full depth and hold the bottom position for 2 to 3 seconds, staying tight.', 'Drive up out of the hole.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Single-Leg_RDL_Bodyweight', 'Single-Leg RDL (Bodyweight)', array['Single-Leg Romanian Deadlift Bodyweight', 'BW Single-Leg RDL']::text[], 'strength', 'hinge', 'compound', 'pull', 'beginner', array['Stand on one leg with a soft knee and your hands hanging in front.', 'Hinge at the hips, sending the other leg straight back as your torso lowers toward parallel.', 'Squeeze your glute to stand tall. Complete all reps, then switch legs.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Slider_Hamstring_Curl', 'Slider Hamstring Curl', array['Towel Hamstring Curl']::text[], 'strength', 'isolation', 'isolation', 'pull', 'intermediate', array['Lie on your back with your heels on sliders or towels on a smooth floor and lift your hips into a bridge.', 'Slide your heels toward your glutes while keeping your hips high.', 'Slide back out slowly.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Smith_Machine_Reverse_Lunge', 'Smith Machine Reverse Lunge', array['Smith Reverse Lunge']::text[], 'strength', 'lunge', 'compound', 'push', 'beginner', array['Set the bar at shoulder height, rest it on your upper back, and stand slightly in front of the bar.', 'Step one foot back and lower your back knee toward the floor.', 'Push through your front foot to return, then switch legs.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Suspension_Pistol_Squat', 'Suspension Pistol Squat', array['TRX Pistol Squat', 'Assisted Pistol Squat']::text[], 'strength', 'lunge', 'compound', 'push', 'intermediate', array['Hold the handles with straight arms, standing on one leg with the other leg out in front.', 'Squat down on the standing leg, using the straps to help balance.', 'Pull yourself back up using as little arm help as you can.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Back_Extension_Machine_Seated', 'Back Extension Machine (Seated)', array['Seated Back Extension', 'Lower Back Machine']::text[], 'strength', 'hinge', 'compound', 'pull', 'beginner', array['Sit in the machine with your back against the pad and the roller set at your upper back.', 'Push back against the pad by extending at your hips and lower back.', 'Return slowly. Use a light weight and a moderate range.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Weighted_Back_Extension', 'Weighted Back Extension', array['Weighted Hyperextension', 'Weighted 45-Degree Back Extension']::text[], 'strength', 'hinge', 'compound', 'pull', 'intermediate', array['Set up in a back extension bench with your hips at the edge of the pad, holding a plate or dumbbell at your chest.', 'Lower your torso with a flat back until you feel your hamstrings stretch.', 'Raise yourself back to a straight line, squeezing your glutes, without overarching.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Butterfly_Stretch', 'Butterfly Stretch', array['Butterfly Pose', 'Seated Butterfly']::text[], 'stretching', 'mobility', null, 'static', 'beginner', array['Sit tall with the soles of your feet together and your knees falling out.', 'Hold your feet and gently press your knees toward the floor.', 'Hold, breathing slowly. Lean forward slightly for a deeper stretch.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Frog_Stretch', 'Frog Stretch', array['Frog Pose', 'Adductor Rock Back']::text[], 'stretching', 'mobility', null, 'static', 'beginner', array['Start on your hands and knees and widen your knees as far as is comfortable, with your feet turned out.', 'Lower onto your forearms and gently rock your hips back toward your heels.', 'Hold and breathe. Come out of it slowly.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Happy_Baby', 'Happy Baby', array['Happy Baby Pose']::text[], 'stretching', 'mobility', null, 'static', 'beginner', array['Lie on your back and bring your knees toward your armpits.', 'Hold the outsides of your feet and pull your knees gently down and apart.', 'Rock gently side to side and hold, breathing slowly.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Knee-to-Wall_Ankle_Mobilization', 'Knee-to-Wall Ankle Mobilization', array['Ankle Mobilization', 'Knee to Wall Stretch', 'Ankle Dorsiflexion Stretch']::text[], 'stretching', 'mobility', null, 'static', 'beginner', array['Stand facing a wall with one foot a few inches back from it.', 'Drive your knee forward to touch the wall without lifting your heel.', 'Move the foot back a little at a time to find your limit. Switch feet.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Sleeper_Stretch', 'Sleeper Stretch', array['Sleeper Shoulder Stretch']::text[], 'stretching', 'mobility', null, 'static', 'beginner', array['Lie on your side with your bottom arm bent at 90 degrees in front of you.', 'Use your other hand to gently press your forearm toward the floor.', 'Stop at a mild stretch in the back of your shoulder. Hold, then switch sides.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Band_Front_Raise', 'Band Front Raise', array['Resistance Band Front Raise']::text[], 'strength', 'isolation', 'isolation', 'pull', 'beginner', array['Stand on a band holding the ends, arms down in front of your thighs.', 'Raise your arms straight up in front of you to shoulder height.', 'Lower slowly under control.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Dumbbell_Rear_Delt_Row', 'Dumbbell Rear Delt Row', array['DB Rear Delt Row', 'Dumbbell Row Elbows Out']::text[], 'strength', 'horizontal_pull', 'compound', 'pull', 'beginner', array['Hold dumbbells with an overhand grip and hinge forward with a flat back.', 'Row the weights up with your elbows flared wide, toward your shoulder height.', 'Squeeze your upper back, then lower slowly.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Dumbbell_Z_Press', 'Dumbbell Z Press', array['DB Z Press', 'Seated Floor Dumbbell Press']::text[], 'strength', 'other', 'compound', 'push', 'expert', array['Sit on the floor with your legs straight in front of you and dumbbells at your shoulders.', 'Press the dumbbells straight overhead without leaning back.', 'Lower to your shoulders under control.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Incline_Dumbbell_Reverse_Fly', 'Incline Dumbbell Reverse Fly', array['Chest-Supported Reverse Fly', 'Incline Rear Delt Fly']::text[], 'strength', 'isolation', 'isolation', 'pull', 'beginner', array['Set a bench to a low incline and lie face down on it with a dumbbell in each hand, arms hanging.', 'Raise your arms out to the sides to shoulder height with a slight bend in your elbows.', 'Lower slowly. The bench keeps you from swinging.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Incline_Dumbbell_Y-Raise', 'Incline Dumbbell Y-Raise', array['Prone Incline Y Raise', 'Chest-Supported Y Raise']::text[], 'strength', 'isolation', 'isolation', 'pull', 'intermediate', array['Lie face down on an incline bench with light dumbbells hanging down and thumbs pointing up.', 'Raise your arms forward and up in a Y shape in line with your ears.', 'Lower slowly. Use light weights.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Suspension_Y_T_Raise', 'Suspension Y/T Raise', array['TRX Y Raise', 'TRX T Raise', 'Ring Y Raise']::text[], 'strength', 'isolation', 'isolation', 'pull', 'intermediate', array['Hold the handles and lean back with straight arms and your body in a straight line.', 'Pull your arms out and up into a Y shape, or out to the sides in a T.', 'Lower slowly. Walk your feet forward for an easier version.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Smith_Machine_Shrug', 'Smith Machine Shrug', array['Smith Shrug']::text[], 'strength', 'isolation', 'isolation', 'pull', 'beginner', array['Stand holding the Smith bar in front of your thighs with arms straight.', 'Shrug your shoulders straight up toward your ears.', 'Hold briefly, then lower slowly.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Cross-Body_Cable_Extension', 'Cross-Body Cable Extension', array['Cross-Body Cable Triceps Extension', 'Cable Cross Body Extension']::text[], 'strength', 'isolation', 'isolation', 'push', 'intermediate', array['Set a cable high and hold the handle in one hand, with your upper arm at your side and elbow bent.', 'Press your hand down and across your body until your arm is straight.', 'Return slowly. Complete all reps, then switch arms.']::text[], '{}'::text[], true, true, 'catalog')
