-- Exercise library batch 3: 65 more exercises from the audit (cable and suspension variations, bodyweight core and
-- glute work, carries, mobility, and a few class-style cardio logs), plus 4 new equipment items: sliders, hand gripper,
-- rotary torso machine and back extension machine. Mirrors scripts/catalog-data.mjs (also in the regenerated catalog
-- seed). Data only, safe to re-run. Nothing existing changes.
-- 65 exercises: Assisted_Chin-Up, Band_Straight-Arm_Pulldown, Jumping_Pull-Up, Suspension_Bicep_Curl, HIIT_Class, Pilates_Session, Rucking, Yoga_Session, Decline_Cable_Fly, Hindu_Push-Up, Lying_Cable_Pullover, Paused_Bench_Press, Single-Arm_Cable_Chest_Press, Spiderman_Push-Up, Suspension_Chest_Fly, Burpee_Box_Jump-Over, Devil_Press, Double-Unders, Medicine_Ball_Rotational_Throw, Shadow_Boxing, Bear_Plank_Hold, Body_Saw, Bosu_Crunch, Decline_Sit-Up, Front_Rack_Carry, High_Plank, Hollow_Rock, Overhead_Carry, Plank_Jacks, RKC_Plank, Rotary_Torso_Machine, Side_Plank_Hip_Dip, Slider_Mountain_Climber, Standing_Oblique_Crunch, Stir_the_Pot, Weighted_Dead_Bug, Hand_Gripper, Band_Seated_Hip_Abduction, Frog_Pump, Side-Lying_Hip_Adduction, Bodyweight_Step-Up, Cable_Standing_Leg_Curl, Cossack_Squat, Dumbbell_Curtsy_Lunge, Heel-Elevated_Goblet_Squat, Pause_Squat, Single-Leg_RDL_Bodyweight, Slider_Hamstring_Curl, Smith_Machine_Reverse_Lunge, Suspension_Pistol_Squat, Back_Extension_Machine_Seated, Weighted_Back_Extension, Butterfly_Stretch, Frog_Stretch, Happy_Baby, Knee-to-Wall_Ankle_Mobilization, Sleeper_Stretch, Band_Front_Raise, Dumbbell_Rear_Delt_Row, Dumbbell_Z_Press, Incline_Dumbbell_Reverse_Fly, Incline_Dumbbell_Y-Raise, Suspension_Y_T_Raise, Smith_Machine_Shrug, Cross-Body_Cable_Extension

on conflict (id) do update set name = excluded.name, category = excluded.category,
  sort_order = excluded.sort_order, common_at_home = excluded.common_at_home;

on conflict (id) do update set name = excluded.name, aliases = excluded.aliases, category = excluded.category,
  movement_pattern = excluded.movement_pattern, mechanic = excluded.mechanic, force = excluded.force, level = excluded.level,
  instructions = excluded.instructions, images = excluded.images, is_common = excluded.is_common,
  is_active = excluded.is_active, source = excluded.source;

